'use strict';

// TEMPORARY RED reproductions for P1-A (stale ZIP) and P1-B (fabricated Send).
// Deleted after folding permanent A1-A10/B1-B14 coverage into w7-016.

const { test } = require('node:test');
const assert = require('node:assert');
const {
  setup,
  userTurn,
  addTurns,
  composerFixture,
  addComposerAttachmentTile,
  installAcceptedSend,
} = require('./helpers');

test('RED-A: stale composer attachment must not clobber newer canonical archive', async () => {
  const { h, api } = setup();
  api.clearVerifiedProjectArchives();
  const fixture = composerFixture(h);

  const tsNew = Date.parse('2026-10-09T03:31:16');
  api.setVerifiedProjectArchive('audapack', {
    filename: '_AUDAPACK_09.10.26-T03-31-16.zip',
    timestamp: tsNew,
    source: 'archive filename',
  });
  api.setManualArchiveBinding({ project_id: 'audapack', display_name: 'AUDAPACK' });

  addComposerAttachmentTile(h, '_AUDAPACK_08.10.26-T05-14-51.zip');
  api.renderTitlebarIndicators();
  const zipEl = h.dom.querySelector('#acb-archive-timestamp');
  assert.strictEqual(zipEl.textContent, 'ZIP 03:31:16', 'ZIP must show newer canonical, not stale attachment');
  const stored = api.getVerifiedProjectArchive('audapack');
  assert.strictEqual(stored.filename, '_AUDAPACK_09.10.26-T03-31-16.zip', 'canonical store must survive stale attachment');
});

test('RED-A2: repeated unchanged renders perform zero persistent writes', async () => {
  const { h, api } = setup();
  api.clearVerifiedProjectArchives();
  composerFixture(h);
  api.setVerifiedProjectArchive('audapack', {
    filename: '_AUDAPACK_09.10.26-T03-31-16.zip',
    timestamp: Date.parse('2026-10-09T03:31:16'),
    source: 'archive filename',
  });
  api.setManualArchiveBinding({ project_id: 'audapack', display_name: 'AUDAPACK' });
  addComposerAttachmentTile(h, '_AUDAPACK_08.10.26-T05-14-51.zip');
  api.renderTitlebarIndicators();
  const startSets = h.counters.gmSet;
  for (let i = 0; i < 8; i += 1) api.renderTitlebarIndicators();
  assert.strictEqual(h.counters.gmSet - startSets, 0, 'unchanged renders must not write storage');
});

test('RED-B: failed Send + edited draft + late history must not fabricate Send', async () => {
  const { h, api } = setup();
  api.clearSendTrackerStore();
  const convo = 'c:aaaaaaaa-1111-4222-8333-111111111111';
  h.sandbox.location.pathname = '/c/aaaaaaaa-1111-4222-8333-111111111111';

  addTurns(h, [userTurn(h, 'b1b1b1b1-1111-4222-8333-222222222222', 'Old history one')]);
  api.syncSendTrackerFromDOM();
  assert.strictEqual(api.getSendTrackerEntry(convo), null);

  const fixture = composerFixture(h);
  installAcceptedSend(h, fixture);
  fixture.send._sendFails = true;
  fixture.input.textContent = 'Original unsent message';
  fixture.send.click();
  api.syncSendTrackerFromDOM();
  assert.strictEqual(api.getSendTrackerEntry(convo), null, 'failed Send records nothing');
  assert.strictEqual(String(fixture.input.textContent), 'Original unsent message', 'draft remains');

  fixture.input.textContent = 'Edited unsent message';
  addTurns(h, [userTurn(h, 'c2c2c2c2-2222-4222-8333-333333333333', 'Some other historical turn')]);
  api.syncSendTrackerFromDOM();

  assert.strictEqual(api.getSendTrackerEntry(convo), null, 'edited draft + unrelated history must not fabricate a Send');
});

