function manualSendIntentCorroborated(intent, turnId, baseline) {
  if (!intent) return false;
  // An intent armed on an empty composer proves nothing: there was nothing
  // to submit, so no accepted transition can corroborate it.
  const hadPayload = Boolean(intent.composerText) || Number(intent.composerTiles || 0) > 0;
