  api.syncSendTrackerFromDOM();

  const first = api.getSendTrackerEntry(convo);
  assert.ok(first, 'accepted Send recorded');
  assert.strictEqual(first.provenance, 'observed');

  h.advance(5000);
  api.syncSendTrackerFromDOM();
  h.advance(5000);
  api.syncSendTrackerFromDOM();
  h.advance(5000);
  api.syncSendTrackerFromDOM();

