'use strict';
// Usage: node .tmp-oldtest/measure.js <tree>  (tree = "." or ".tmp-oldtest")
const tree = process.argv[2] || '.';
const { setup, composerFixture, addComposerAttachmentTile } = require(`../${tree}/tests/widget/helpers`);

function stubWallClock(h, startMs) {
  let fakeNow = startMs;
  h.sandbox.Date.now = () => fakeNow;
  return { advance: ms => { fakeNow += ms; h.advance(ms); } };
}

async function m3() {
  const { h, api } = setup();
  api.clearVerifiedProjectArchives();
  composerFixture(h);
  api.setVerifiedProjectArchive('audapack', {
    filename: '_AUDAPACK_09.10.26-T03-31-16.zip',
    timestamp: Date.parse('2026-10-09T03:31:16'), source: 'archive filename'
  });
  api.setManualArchiveBinding({ project_id: 'audapack', display_name: 'AUDAPACK' });
  addComposerAttachmentTile(h, '_AUDAPACK_08.10.26-T05-14-51.zip');
  api.renderTitlebarIndicators();
  const start = h.counters.gmSet;
  for (let i = 0; i < 10; i += 1) api.renderTitlebarIndicators();
  console.log(`M3 [${tree}] GM_setValue across 10 unchanged renders: ${h.counters.gmSet - start}`);
}

async function m4() {
  const { h, api } = setup();
  const clock = stubWallClock(h, Date.now());
  api.storage.gmSet('ai_chatbuttons_bridge_token_v1', 'test-token');
  api.clearVerifiedProjectArchives();
  const ts = Date.parse('2026-10-09T03:31:16');
  const state = { requests: 0, fail: false, projectId: 'audapack', filename: '_AUDAPACK_09.10.26-T03-31-16.zip', mtime: ts };
  h.httpResponder = options => {
    if (String(options?.url || '').includes('/archive/metadata')) {
      state.requests += 1;
      return { status: 200, responseText: JSON.stringify({ ok: true, project_id: state.projectId, filename: state.filename, mtime: Math.floor(state.mtime / 1000) }) };
    }
    return { status: 404 };
  };
  api.setVerifiedProjectArchive('audapack', { filename: state.filename, timestamp: ts, source: 'archive filename' });
  api.setManualArchiveBinding({ project_id: 'audapack', display_name: 'AUDAPACK' });
  api.renderTitlebarIndicators();
  api.startSendAgeTimer();
  api.startArchiveMetadataPoll();
  await h.settle();
  const startSets = h.counters.gmSet;
  for (let i = 0; i < 60; i += 1) { clock.advance(1000); }
  await h.settle();
  console.log(`M4 [${tree}] metadata requests across 60s idle: ${state.requests}, GM_setValue in window: ${h.counters.gmSet - startSets}`);
  api.cancelSendAgeTimer();
  api.cancelArchiveMetadataPoll();
}

async function m5() {
  const { h, api } = setup();
  composerFixture(h);
  api.renderTitlebarIndicators();
  api.startSendAgeTimer();
  const q0 = h.counters.qsa; const g0 = h.counters.gmGet;
  for (let i = 0; i < 10; i += 1) h.advance(1000);
  console.log(`M5 [${tree}] 10 SEND ticks: qsa delta=${h.counters.qsa - q0}, gmGet delta=${h.counters.gmGet - g0}`);
  api.cancelSendAgeTimer();
}

async function m6() {
  const { h, api } = setup();
  const base = h.timers.pending().length;
  for (let i = 0; i < 5; i += 1) { api.mount(); api.startSendAgeTimer(); api.startArchiveMetadataPoll(); }
  const peak = h.timers.pending().length - base;
  api.cancelSendAgeTimer();
  api.cancelArchiveMetadataPoll();
  const rest = h.timers.pending().length - base;
  console.log(`M6 [${tree}] timers after 5x mount: +${peak} (expect 2), after teardown: +${rest} (expect 0)`);
}

(async () => { await m3(); await m4(); await m5(); await m6(); })().catch(e => { console.error(e); process.exit(1); });

